        <Message
            at="2025-03-23T20:19:02.049590Z"
        >
            <Origin>74b85301-f8f9-4268-addb-0d2c42603ec4</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                No, a truly formal proof in first-order logic would not typically begin with the word "Assume." In strictly
                formal proofs as presented in logic textbooks and formal systems, each line consists only of the formula
                itself followed by its justification, without natural language phrases like "Assume."
            </Paragraph>
            <Paragraph>
                What I presented in my tutorial used some natural language for readability, but in a fully formal proof
                system, assumptions would be indicated through specific notation. Here's how assumptions are typically
                handled in strictly formal notation:
            </Paragraph>
            <Paragraph>
                For a proof by contradiction, instead of writing "Assume ¬φ," a formal proof would use one of these
                approaches:
            </Paragraph>
            <Paragraph>
                <List ordered />
                <Line>
                    <Word>
                        <Bold />
                        Subproof notation
                    </Word>: Use brackets, indentation, or a vertical line to indicate a subproof where the assumption is
                    being made: ```
                </Line>
                <Paragraph>
                    <List ordered />
                    <Line>&#91;¬φ                           &#91;Assumption&#93;</Line>
                    <Paragraph>
                        <List ordered />
                        <Line>
                            ... n. ψ ∧ ¬ψ &#91;Contradiction&#93; &#93; n+1. ¬¬φ &#91;1-n, RAA&#93; n+2. φ &#91;n+1,
                            ¬¬E&#93; ```
                        </Line>
                    </Paragraph>
                </Paragraph>
                <Line>
                    <Word>
                        <Bold />
                        Conditional proof notation
                    </Word>: If using a natural deduction system: ```
                </Line>
                <Paragraph>
                    <List ordered />
                    <Line>
                        ¬φ &#91;A&#93; (where A stands for assumption) ... n. ψ ∧ ¬ψ &#91;Derived&#93; n+1. ¬φ → (ψ ∧ ¬ψ)
                        &#91;1-n, →I&#93; n+2. ¬¬φ &#91;n+1, RAA&#93; n+3. φ &#91;n+2, ¬¬E&#93; ```
                    </Line>
                </Paragraph>
                <Line>
                    <Word>
                        <Bold />
                        Sequent calculus notation
                    </Word>: Using the turnstile symbol: ```
                </Line>
                <Paragraph>
                    <List ordered />
                    <Line>
                        ¬φ ⊢ ¬φ &#91;Axiom&#93; ... n. ¬φ ⊢ ψ ∧ ¬ψ &#91;Derived&#93; n+1. ⊢ ¬φ → (ψ ∧ ¬ψ) &#91;n, →I&#93;
                        n+2. ⊢ ¬¬φ &#91;n+1, RAA&#93; n+3. ⊢ φ &#91;n+2, ¬¬E&#93; ```
                    </Line>
                </Paragraph>
            </Paragraph>
            <Paragraph>
                In formal logic textbooks like Mendelson's "Introduction to Mathematical Logic" or Enderton's "A
                Mathematical Introduction to Logic," proofs are presented with this level of formality, where assumptions
                are indicated through the proof system's notation rather than through words like "Assume."
            </Paragraph>
            <Paragraph>
                Thank you for the correction - it's an important distinction between the more readable, slightly informal
                presentation I gave and the strictly formal notation of mathematical logic.
            </Paragraph>
        </Message>
